// ---- edit these ----
const TEST_RECIPIENT = ''; // demo: put your own email here and every mail goes to it. Leave empty for real use.
const ADMIN_EMAIL = 'admin@yourcompany.com';
const APP_URL = 'http://localhost:5173/app';
// --------------------

const data = $input.first().json;
const out = [];
const plural = (n, word) => n + ' ' + word + (n === 1 ? '' : 's');

for (const a of data.approvers || []) {
  const text = [
    'Hi ' + a.name + ',',
    '',
    'You have ' + plural(a.pending_count, 'invoice') + ' waiting for your approval.',
    'The oldest has been waiting ' + plural(a.oldest_pending_days, 'day') + '.',
    '',
    'Review them here: ' + APP_URL + '/approvals',
    '',
    '- BillFlow'
  ].join('\n');
  out.push({
    json: {
      to: TEST_RECIPIENT || a.email,
      subject: 'BillFlow: pending approvals waiting (' + a.pending_count + ')',
      text
    }
  });
}

const failed = data.sync_failed || 0;
const review = data.needs_review || 0;
if (failed > 0 || review > 0) {
  const text = [
    'Daily BillFlow check:',
    '',
    '- ' + plural(failed, 'invoice') + ' failed to post to Tally (see ' + APP_URL + '/reconciliation)',
    '- ' + plural(review, 'invoice') + ' waiting for review (see ' + APP_URL + '/invoices)',
    '',
    '- BillFlow'
  ].join('\n');
  out.push({
    json: {
      to: TEST_RECIPIENT || ADMIN_EMAIL,
      subject: 'BillFlow: items need attention',
      text
    }
  });
}

return out;
